#' Save Zymoseptoria reference sequences to a FASTA file
#'
#' This function defines a set of DNA sequences (CYP51, CYTB, SDHB, SDHC, SDHD) 
#' for the fungus \emph{Zymoseptoria}, and then saves them in FASTA format 
#' in the current working directory.
#'
#' @return Returns an invisible \code{DNAStringSet} object containing the defined sequences.
#' @export
#'
#' @examples
#' \dontrun{
#' get_reference_sequences()
#' }

get_reference_sequences <- function(){

  CYP51_reference <- Biostrings::DNAString("")
  CYTB_reference <- Biostrings::DNAString("CCTCATACGAATTCAACTATGTCTTGTCCAACTCAAGGTATTGCACTCAATAAGTTAGTTATAACTGTTGCTCCTCATAAAGACATTTGACCATAAGGTAATACATACCCTAAGAATGCGGTTGCCATCATCAGAACTAGTATTATAGTACCGATTGTTCATGTTAATGTTCTAGGGGCTTTGTA")
  SDHB_reference <- Biostrings::DNAString("")
  SDHC_reference <- Biostrings::DNAString("")
  SDHD_reference <- Biostrings::DNAString("")

  ref_set <- Biostrings::DNAStringSet(c(
    CYP51 = CYP51_reference,
    CYTB  = CYTB_reference,
    SDHB  = SDHB_reference,
    SDHC  = SDHC_reference,
    SDHD  = SDHD_reference
  ))
  
  file_path <- "reference_zymoseptoria.fasta"
  Biostrings::writeXStringSet(ref_set, filepath = file_path)
  
  message(paste("Sequence successfully saved in:", getwd()))
  return(invisible(ref_set))
}